create function public.recipe_assert(ok boolean,msg text) returns void language plpgsql as $$ begin if not coalesce(ok,false) then raise exception 'Assertion failed: %',msg; end if; end; $$;
create function public.recipe_denied(stmt text,expected text) returns void language plpgsql as $$ begin begin execute stmt; exception when others then if sqlstate=expected then return; end if; raise; end; raise exception 'Expected failure: %',stmt; end; $$;
grant execute on function public.recipe_assert(boolean,text),public.recipe_denied(text,text) to authenticated;

