create function public.fail_recipe_audit() returns trigger language plpgsql as $$ begin if new.action='RECIPE_CREATED' then raise exception 'Forced audit failure' using errcode='23514'; end if; return new; end; $$;
create trigger fail_recipe_audit before insert on public.audit_events for each row execute function public.fail_recipe_audit();
